import React,{useCallback,useEffect,useState} from "react";
import {api} from "./api";

const money=(value,currency="KES")=>new Intl.NumberFormat("en-KE",{style:"currency",currency,maximumFractionDigits:2}).format(Number(value||0));
const today=()=>new Date().toISOString().slice(0,10);
function Panel({title,children,action}){return <section className="panel"><div className="panel-head"><h3>{title}</h3>{action}</div>{children}</section>}
function Metric({label,value,detail}){return <div className="portal-metric"><span>{label}</span><strong>{value??"—"}</strong>{detail&&<small>{detail}</small>}</div>}
function ErrorLine({value}){return value?<div className="alert error" role="alert">{value}</div>:null}

export function FinancePortal(){
 const [accounts,setAccounts]=useState([]),[trial,setTrial]=useState(null),[journals,setJournals]=useState([]),[invoices,setInvoices]=useState([]),[periods,setPeriods]=useState([]),[cash,setCash]=useState(null),[aging,setAging]=useState(null);
 const [tab,setTab]=useState("overview"),[start,setStart]=useState(new Date(new Date().getFullYear(),0,1).toISOString().slice(0,10)),[end,setEnd]=useState(today()),[cashIds,setCashIds]=useState([]),[error,setError]=useState(""),[busy,setBusy]=useState(false);
 const load=useCallback(async()=>{setBusy(true);setError("");const results=await Promise.allSettled([
  api("/api/v1/accounting/accounts"),api("/api/v1/accounting/trial-balance"),api("/api/v1/accounting/journals?limit=100"),api("/api/v1/accounting/invoices?limit=100"),api("/api/v1/accounting/fiscal-periods"),api("/api/v1/accounting/aging?invoice_type=receivable"),api("/api/v1/accounting/aging?invoice_type=payable")
 ]);const [a,t,j,i,p,ar,ap]=results;const failures=[];
 if(a.status==="fulfilled"){setAccounts(a.value);setCashIds(old=>old.length?old:a.value.filter(x=>x.account_type==="asset").slice(0,1).map(x=>String(x.id)))}else failures.push("Accounts: "+a.reason.message);
 if(t.status==="fulfilled")setTrial(t.value);else failures.push("Trial balance: "+t.reason.message);
 if(j.status==="fulfilled")setJournals(j.value);else failures.push("Journals: "+j.reason.message);
 if(i.status==="fulfilled")setInvoices(i.value);else failures.push("Invoices: "+i.reason.message);
 if(p.status==="fulfilled")setPeriods(p.value);else failures.push("Fiscal periods: "+p.reason.message);
 if(ar.status==="fulfilled")setAging(ar.value);else failures.push("Receivables aging: "+ar.reason.message);
 if(ap.status==="fulfilled")setAging(old=>({...old,payables:ap.value}));
 setError(failures.join(" · "));setBusy(false);
 },[]);
 useEffect(()=>{load()},[load]);
 async function loadCash(e){e?.preventDefault();if(!cashIds.length){setError("Select at least one asset/bank account for the cash-flow report.");return}setBusy(true);setError("");try{const q=new URLSearchParams({start_date:start,end_date:end});cashIds.forEach(id=>q.append("cash_account_ids",id));setCash(await api("/api/v1/accounting/cash-flow?"+q.toString()))}catch(err){setError(err.message)}finally{setBusy(false)}}
 const posted=invoices.filter(x=>x.status!=="draft"),receivable=invoices.filter(x=>x.invoice_type==="receivable"),payable=invoices.filter(x=>x.invoice_type==="payable");
 const tabs=[["overview","Overview"],["invoices","AR / AP"],["ledger","Ledger"],["reports","Reports"]];
 return <div className="industry-workspace"><div className="portal-toolbar">{tabs.map(([id,label])=><button key={id} className={tab===id?"primary":"secondary"} onClick={()=>setTab(id)}>{label}</button>)}<button className="secondary" onClick={load} disabled={busy}>{busy?"Loading…":"Refresh"}</button></div><ErrorLine value={error}/>
 {tab==="overview"&&<><div className="portal-metrics"><Metric label="Chart of accounts" value={accounts.length}/><Metric label="Posted invoices" value={posted.length}/><Metric label="Receivables" value={receivable.length}/><Metric label="Payables" value={payable.length}/><Metric label="Fiscal periods" value={periods.length}/><Metric label="Trial balance" value={trial?(trial.balanced?"Balanced":"Out of balance"):"—"} detail={trial?money(trial.total_debits):"Awaiting ledger data"}/></div><div className="portal-columns"><Panel title="Trial balance"><p className="muted">Ledger-derived balances from posted journals.</p><div className="portal-list">{(trial?.accounts||[]).slice(0,8).map(x=><div className="resource-row" key={x.account_id}><div><strong>{x.code} · {x.name}</strong><small>{x.account_type}</small></div><span>{money(Number(x.debits)-Number(x.credits))}</span></div>)}</div></Panel><Panel title="Recent posted journals"><div className="portal-list">{journals.slice(0,8).map(x=><div className="resource-row" key={x.id}><div><strong>{x.journal_number}</strong><small>{x.entry_date} · {x.reference||x.memo||"Journal"}</small></div><span className="status">{x.status}</span></div>)}{!journals.length&&<p className="empty">No posted journals returned by the API.</p>}</div></Panel></div></>}
 {tab==="invoices"&&<div className="portal-columns"><Panel title="Accounts receivable"><div className="portal-list">{receivable.map(x=><div className="resource-row" key={x.id}><div><strong>{x.invoice_number}</strong><small>Due {x.due_date} · {x.status}</small></div><div><strong>{money(x.balance,x.currency)}</strong><small>{money(x.total,x.currency)} total</small></div></div>)}{!receivable.length&&<p className="empty">No receivable invoices.</p>}</div></Panel><Panel title="Accounts payable"><div className="portal-list">{payable.map(x=><div className="resource-row" key={x.id}><div><strong>{x.invoice_number}</strong><small>Due {x.due_date} · {x.status}</small></div><div><strong>{money(x.balance,x.currency)}</strong><small>{money(x.total,x.currency)} total</small></div></div>)}{!payable.length&&<p className="empty">No payable invoices.</p>}</div></Panel></div>}
 {tab==="ledger"&&<div className="portal-columns"><Panel title="Chart of accounts"><div className="portal-list">{accounts.map(x=><div className="resource-row" key={x.id}><div><strong>{x.code} · {x.name}</strong><small>{x.account_type}</small></div><span className="status">Active</span></div>)}{!accounts.length&&<p className="empty">No accounts returned by the API.</p>}</div></Panel><Panel title="Posted journal register"><div className="portal-list">{journals.map(x=><div className="resource-row" key={x.id}><div><strong>{x.journal_number}</strong><small>{x.entry_date} · {x.reference||"No reference"}</small><small>{x.memo||""}</small></div><span className="status">{x.status}</span></div>)}{!journals.length&&<p className="empty">No posted journals.</p>}</div></Panel></div>}
 {tab==="reports"&&<><Panel title="Cash-flow report"><p className="muted">Uses posted ledger journals and the selected asset accounts. Classification is derived by the backend from counterpart account types.</p><form className="stack-form" onSubmit={loadCash}><div className="portal-form-grid"><label>Start date<input type="date" required value={start} onChange={e=>setStart(e.target.value)}/></label><label>End date<input type="date" required min={start} value={end} onChange={e=>setEnd(e.target.value)}/></label></div><label className="portal-field">Cash / bank accounts<select multiple value={cashIds} onChange={e=>setCashIds(Array.from(e.target.selectedOptions).map(x=>x.value))}>{accounts.filter(x=>x.account_type==="asset").map(x=><option key={x.id} value={String(x.id)}>{x.code} · {x.name}</option>)}</select><small>Choose only asset accounts used as cash or bank accounts.</small></label><button className="primary" disabled={busy||!cashIds.length}>Run cash-flow report</button></form>{cash&&<div className="portal-metrics"><Metric label="Opening balance" value={money(cash.opening_balance)}/><Metric label="Operating" value={money(cash.operating)}/><Metric label="Investing" value={money(cash.investing)}/><Metric label="Financing" value={money(cash.financing)}/><Metric label="Net change" value={money(cash.net_change)}/><Metric label="Closing balance" value={money(cash.closing_balance)}/></div>}</Panel><div className="portal-columns"><Panel title="Receivables aging"><div className="portal-list">{Object.entries(aging?.buckets||{}).map(([k,v])=><div className="resource-row" key={k}><strong>{k.replaceAll("_","–")}</strong><span>{money(v)}</span></div>)}</div></Panel><Panel title="Payables aging"><div className="portal-list">{Object.entries(aging?.payables?.buckets||{}).map(([k,v])=><div className="resource-row" key={k}><strong>{k.replaceAll("_","–")}</strong><span>{money(v)}</span></div>)}</div></Panel></div><Panel title="Fiscal periods"><div className="portal-list">{periods.map(x=><div className="resource-row" key={x.id}><div><strong>{x.code}</strong><small>{x.start_date} – {x.end_date}</small></div><span className="status">{x.status}</span></div>)}{!periods.length&&<p className="empty">No fiscal periods.</p>}</div></Panel></>}
 </div>
}

