 const load=useCallback(async()=>{setBusy(true);setError("");const rs=await Promise.allSettled([api("/api/v1/hr/employees"),api("/api/v1/hr/leave-requests"),api("/api/v1/payroll/rule-sets"),api("/api/v1/payroll/runs"),api("/api/v1/branches"),api("/api/v1/accounting/accounts"),api("/api/v1/payroll/accounting-mapping"),api("/api/v1/hr/attendance"),api("/api/v1/payroll/payment-batches"),api("/api/v1/hr/payroll-adjustments")]);const fails=[];if(rs[0].status==="fulfilled")setEmployees(rs[0].value);else fails.push("Employees: "+rs[0].reason.message);if(rs[1].status==="fulfilled")setLeaves(rs[1].value);else fails.push("Leave: "+rs[1].reason.message);if(rs[2].status==="fulfilled")setRules(rs[2].value);else fails.push("Rules: "+rs[2].reason.message);if(rs[3].status==="fulfilled")setRuns(rs[3].value);else fails.push("Payroll: "+rs[3].reason.message);if(rs[4].status==="fulfilled")setBranches(rs[4].value);else fails.push("Branches: "+rs[4].reason.message);if(rs[5].status==="fulfilled")setAccounts(rs[5].value);else fails.push("Accounting accounts: "+rs[5].reason.message);if(rs[6].status==="fulfilled"){setMapping(rs[6].value);if(rs[6].value)setMappingForm(Object.fromEntries(Object.keys(mappingForm).map(k=>[k,String(rs[6].value[k]||"")])))}else fails.push("Payroll mapping: "+rs[6].reason.message);if(rs[7].status==="fulfilled")setAttendance(rs[7].value);else fails.push("Attendance: "+rs[7].reason.message);if(rs[8].status==="fulfilled")setPaymentBatches(rs[8].value);else fails.push("Payment batches: "+rs[8].reason.message);if(rs[9].status==="fulfilled")setAdjustments(rs[9].value);else fails.push("Payroll adjustments: "+rs[9].reason.message);setError(fails.join(" · "));setBusy(false)},[]);
 useEffect(()=>{load()},[load]);
 async function changeEmploymentStatus(row){const terminationDate=window.prompt("Termination date (YYYY-MM-DD):",today());if(!terminationDate)return;if(!/^\d{4}-\d{2}-\d{2}$/.test(terminationDate)){setError("Enter the termination date as YYYY-MM-DD.");return}const reason=window.prompt("Reason for termination (required):");if(!reason||reason.trim().length<3){setError("A termination reason of at least 3 characters is required.");return}setBusy(true);setError("");try{await api("/api/v1/hr/employees/"+row.id+"/employment-status",{method:"POST",body:JSON.stringify({status:"terminated",termination_date:terminationDate,reason:reason.trim()})});setNotice(row.employee_number+" marked as terminated. Historical payroll snapshots remain unchanged.");await load()}catch(err){setError(err.message)}finally{setBusy(false)}}
 async function createEmployee(e){e.preventDefault();setBusy(true);setError("");try{await api("/api/v1/hr/employees",{method:"POST",body:JSON.stringify({...employee,branch_id:employee.branch_id||null,recurring_allowances:JSON.parse(employee.recurring_allowances),recurring_benefits:JSON.parse(employee.recurring_benefits),scheduled_minutes_per_day:Number(employee.scheduled_minutes_per_day),overtime_multiplier:employee.overtime_multiplier===""?null:Number(employee.overtime_multiplier)})});setNotice("Employee profile created.");setEmployee(x=>({...x,employee_number:"",first_name:"",last_name:"",base_salary:""}));await load()}catch(e){setError(e.message)}finally{setBusy(false)}}
 async function createLeave(e){e.preventDefault();setBusy(true);setError("");try{await api("/api/v1/hr/employees/"+leave.employee_id+"/leave",{method:"POST",body:JSON.stringify({...leave,employee_id:undefined,days:Number(leave.days)})});setNotice("Leave request submitted for review.");await load()}catch(e){setError(e.message)}finally{setBusy(false)}}
 async function createAttendance(e){e.preventDefault();setBusy(true);setError("");try{const toOffsetIso=value=>{const d=new Date(value);const offset=-d.getTimezoneOffset();const sign=offset>=0?"+":"-";const hh=String(Math.floor(Math.abs(offset)/60)).padStart(2,"0");const mm=String(Math.abs(offset)%60).padStart(2,"0");const wall=new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,19);return wall+sign+hh+":"+mm};const body={employee_id:Number(attendanceForm.employee_id),work_date:attendanceForm.work_date,clock_in:toOffsetIso(attendanceForm.clock_in),clock_out:toOffsetIso(attendanceForm.clock_out),break_minutes:Number(attendanceForm.break_minutes),scheduled_minutes:Number(attendanceForm.scheduled_minutes),idempotency_key:attendanceForm.idempotency_key||("att-"+Date.now()+"-"+Math.random().toString(36).slice(2,10))};await api("/api/v1/hr/attendance",{method:"POST",body:JSON.stringify(body)});setNotice("Attendance submitted for independent review.");setAttendanceForm(x=>({...x,clock_in:"",clock_out:"",idempotency_key:""}));await load()}catch(e){setError(e.message)}finally{setBusy(false)}}
